SELECT N.CODNAT AS NATUREZA_ID, N.DESCRNAT AS NATUREZA_NOME, P.CODPROJ AS PROJETO_ID, P.IDENTIFICACAO AS PROJETO_NOME, CR.DESCRCENCUS AS CR_NOME, SUM(CASE WHEN T.CODMETA <> 3 THEN T.PREVREC - T.PREVDESP ELSE 0 END) AS VL_ORCADO, SUM(T.BAIXA_REC - T.BAIXA_DESP) AS VL_REALIZADO, SUM(T.COMP_REC - T.COMP_DESP) AS VL_COMPETENCIA, SUM(CASE WHEN T.CODMETA = 3 THEN T.PREVREC - T.PREVDESP ELSE 0 END) AS VL_FORECAST FROM Orcamentos T JOIN Natureza N ON T.CODNAT = N.CODNAT JOIN Projetos P ON T.CODPROJ = P.CODPROJ JOIN CentroResultado CR ON T.CODCENCUS = CR.CODCENCUS WHERE ( TRUNC(T.DTREF) >= TO_DATE(SUBSTR(:VAR_DRE_DT_INI,1,10),'YYYY-MM-DD') OR :VAR_DRE_DT_INI IS NULL OR :VAR_DRE_DT_INI = '' ) AND ( TRUNC(T.DTREF) <= TO_DATE(SUBSTR(:VAR_DRE_DT_FIM,1,10),'YYYY-MM-DD') OR :VAR_DRE_DT_FIM IS NULL OR :VAR_DRE_DT_FIM = '' ) AND ( :VAR_DRE_EMP IS NULL OR LTRIM(RTRIM(:VAR_DRE_EMP)) = '' OR INSTR(',' || :VAR_DRE_EMP || ',', ',' || T.CODEMP || ',') > 0 ) AND ( :VAR_DRE_CODMETA IS NULL OR LTRIM(RTRIM(:VAR_DRE_CODMETA)) = '' OR INSTR(',' || :VAR_DRE_CODMETA || ',', ',' || T.CODMETA || ',') > 0 OR T.CODMETA = 3 ) AND ( :VAR_DRE_GESTOR_CR IS NULL OR LTRIM(RTRIM(:VAR_DRE_GESTOR_CR)) = '' OR INSTR(',' || :VAR_DRE_GESTOR_CR || ',', ',' || CR.CODCENCUS || ',') > 0 ) AND ( :VAR_DRE_NAT_OCULTAR IS NULL OR LTRIM(RTRIM(:VAR_DRE_NAT_OCULTAR)) = '' OR INSTR(',' || :VAR_DRE_NAT_OCULTAR || ',', ',' || N.CODNAT || ',') = 0 ) AND SUBSTR(N.CODNAT, 1, 1) NOT IN ('8', '9') AND NOT (T.CODEMP IN (1, 2) AND N.CODNAT LIKE '2%') AND NOT (T.CODEMP IN (3, 4, 5, 6) AND N.CODNAT LIKE '3%') GROUP BY N.CODNAT, N.DESCRNAT, P.CODPROJ, P.IDENTIFICACAO, CR.DESCRCENCUS ORDER BY N.DESCRNAT, P.IDENTIFICACAO